// In check_at() or wait_for() task, after mismatch detection:
task automatic check_signal(input int sig_id, input logic [31:0] expected);
  logic [31:0] actual;
  actual = sample_signal(sig_id);
  if (actual !== expected) begin
    mismatch_count++;
    // FIX: Ensure vector capture always executes on failure
    failing_vectors[fail_idx].sig_id = sig_id;
    failing_vectors[fail_idx].cycle = $time / CLK_PERIOD;
    failing_vectors[fail_idx].actual = actual;
    failing_vectors[fail_idx].expected = expected;
    fail_idx++;
    $display("MISMATCH: sig_id=%0d cycle=%0d actual=0x%h expected=0x%h", 
             sig_id, $time/CLK_PERIOD, actual, expected);
  end
endtask

// In reference model init_done timing prediction:
// OLD: expected_init_done_cycle = init_complete_cycle;
// NEW: Account for config_regs input register stage
parameter int CSR_PIPELINE_LATENCY = 1;  // cycles
expected_init_done_csr_visible_cycle = init_complete_cycle + CSR_PIPELINE_LATENCY;

// When generating expected values for CTRL_STATUS[0] checks:
function automatic logic predict_csr_init_done(int check_cycle);
  // init_done visible via CSR is delayed by register stage
  return (check_cycle >= (init_sequence_complete_cycle + CSR_PIPELINE_LATENCY));
endfunction

